"""
linalg.py: Pure Python linear algebra library.
Features: matrix/vector add, multiply, transpose, determinant, inverse (Gauss-Jordan), solving linear systems. No numpy.
All functions are standalone. Input validation for dimensions/types, strong docstring coverage.
"""

from typing import List, Union

Matrix = List[List[float]]
Vector = List[float]

# --- Utility validation ---
def is_matrix(m) -> bool:
    if not isinstance(m, list) or not m:
        return False
    rowlen = len(m[0])
    return all(isinstance(row, list) and len(row) == rowlen for row in m)

def is_vector(v) -> bool:
    return isinstance(v, list) and all(isinstance(x, (int, float)) for x in v)

def shape(mat: Matrix) -> tuple:
    return (len(mat), len(mat[0]) if mat else 0)

# --- Core API ---
def add(a: Union[Matrix, Vector], b: Union[Matrix, Vector]) -> Union[Matrix, Vector]:
    """
    Add two matrices or vectors of the same shape.
    """
    if is_vector(a) and is_vector(b):
        if len(a) != len(b):
            raise ValueError("Vectors must have same length.")
        return [x + y for x, y in zip(a, b)]
    if is_matrix(a) and is_matrix(b):
        if shape(a) != shape(b):
            raise ValueError("Matrices must have same shape.")
        return [[x + y for x, y in zip(r1, r2)] for r1, r2 in zip(a, b)]
    raise ValueError("Inputs must both be vectors or matrices of same shape.")

def multiply(a: Union[Matrix, Vector], b: Union[Matrix, Vector, float, int]) -> Union[Matrix, Vector, float]:
    """
    Multiply matrix × matrix, matrix × vector, or by scalar.
    """
    # Scalar multiplication
    if isinstance(b, (int, float)):
        if is_vector(a):
            return [x * b for x in a]
        if is_matrix(a):
            return [[x * b for x in row] for row in a]
        raise ValueError("a must be matrix or vector for scalar mult.")
    # Vector × Vector (dot)
    if is_vector(a) and is_vector(b):
        if len(a) != len(b):
            raise ValueError("Vectors must be same length.")
        return sum(x*y for x, y in zip(a, b))
    # Matrix × Vector
    if is_matrix(a) and is_vector(b):
        n, m = shape(a)
        if len(b) != m:
            raise ValueError("Matrix cols must match vector length.")
        return [sum(row[j] * b[j] for j in range(m)) for row in a]
    # Matrix × Matrix
    if is_matrix(a) and is_matrix(b):
        n, m = shape(a)
        m2, p = shape(b)
        if m != m2:
            raise ValueError("a cols must match b rows.")
        return [[sum(a[i][k]*b[k][j] for k in range(m)) for j in range(p)] for i in range(n)]
    raise ValueError("Invalid multiply.")

def transpose(mat: Matrix) -> Matrix:
    """
    Transpose a matrix.
    """
    if not is_matrix(mat):
        raise ValueError("Input must be matrix.")
    return [list(row) for row in zip(*mat)]

def determinant(mat: Matrix) -> float:
    """
    Compute the determinant of a square matrix.
    """
    if not is_matrix(mat):
        raise ValueError("Input must be matrix.")
    n, m = shape(mat)
    if n != m:
        raise ValueError("Matrix must be square.")
    # Base cases
    if n == 1:
        return mat[0][0]
    if n == 2:
        return mat[0][0]*mat[1][1] - mat[0][1]*mat[1][0]
    # Recursion (Laplace expansion)
    det = 0.0
    for col in range(n):
        minor = [row[:col] + row[col+1:] for row in mat[1:]]
        det += ((-1) ** col) * mat[0][col] * determinant(minor)
    return det

def inverse(mat: Matrix) -> Matrix:
    """
    Compute the inverse of a square matrix using Gauss-Jordan elimination.
    """
    if not is_matrix(mat):
        raise ValueError("Input must be matrix.")
    n, m = shape(mat)
    if n != m:
        raise ValueError("Matrix must be square.")
    # Make a deep copy
    A = [row[:] for row in mat]
    I = [[float(i == j) for j in range(n)] for i in range(n)]
    for col in range(n):
        # Find pivot
        pivot = A[col][col]
        if abs(pivot) < 1e-15:
            # Try to swap with a row below
            for row in range(col+1, n):
                if abs(A[row][col]) > 1e-15:
                    A[col], A[row] = A[row], A[col]
                    I[col], I[row] = I[row], I[col]
                    pivot = A[col][col]
                    break
            else:
                raise ValueError("Singular matrix (no inverse)")
        # Normalize pivot row
        inv_pivot = 1.0/pivot
        A[col] = [a * inv_pivot for a in A[col]]
        I[col] = [a * inv_pivot for a in I[col]]
        # Eliminate
        for row in range(n):
            if row != col:
                factor = A[row][col]
                A[row] = [a - factor*b for a, b in zip(A[row], A[col])]
                I[row] = [a - factor*b for a, b in zip(I[row], I[col])]
    return I

def solve(A: Matrix, b: Vector) -> Vector:
    """
    Solve Ax = b for x using Gauss-Jordan elimination.
    """
    if not is_matrix(A) or not is_vector(b):
        raise ValueError("A must be matrix and b must be vector.")
    n, m = shape(A)
    if n != m or len(b) != n:
        raise ValueError("Matrix A must be square and len(b)==n.")
    # Form augmented matrix
    M = [A[i][:] + [b[i]] for i in range(n)]
    # Forward elimination
    for col in range(n):
        pivot = M[col][col]
        if abs(pivot) < 1e-15:
            for row in range(col+1, n):
                if abs(M[row][col]) > 1e-15:
                    M[col], M[row] = M[row], M[col]
                    break
            else:
                raise ValueError("Singular matrix.")
            pivot = M[col][col]
        # Normalize
        factor = 1.0/pivot
        M[col] = [x*factor for x in M[col]]
        # Eliminate
        for row in range(n):
            if row != col:
                f = M[row][col]
                M[row] = [a - f*b for a, b in zip(M[row], M[col])]
    x = [M[i][-1] for i in range(n)]
    return x

# --- End of linalg.py ---
